from typing import Sequence

def exact_count(A: int, L: int, pattern: Sequence[int]) -> int:
    q=tuple(pattern); m=len(q)
    def step(r: int, a: int) -> int:
        candidate=q[:r]+(a,)
        return max((k for k in range(1,m+1) if candidate[-k:] == q[:k]), default=0)
    trans=[[step(r,a) for a in range(A)] for r in range(m)]
    dp=[1]+[0]*(m-1)
    for _ in range(L):
        nxt=[0]*m
        for r,count in enumerate(dp):
            for a in range(A):
                s=trans[r][a]
                if s<m: nxt[s]+=count
        dp=nxt
    return A**L-sum(dp)

from typing import List

def de_bruijn(A: int, k: int) -> List[int]:
    work=[0]*(A*k+1); out: List[int]=[]
    def visit(t: int, p: int) -> None:
        if t>k:
            if k%p==0: out.extend(work[1:p+1])
            return
        work[t]=work[t-p]; visit(t+1,p)
        for symbol in range(work[t-p]+1,A):
            work[t]=symbol; visit(t+1,t)
    visit(1,1)
    return out

from itertools import product
from typing import Sequence

def exhaustive_count(A: int, L: int, q: Sequence[int]) -> int:
    target=tuple(q); m=len(target); hits=0
    for word in product(range(A), repeat=L):
        if any(word[i:i+m] == target for i in range(L-m+1)):
            hits += 1
    return hits

